import java.nio.file.*;import java.util.*;import com.google.gson.*;import org.joml.Matrix4f;import io.github.r3neer.scalebrews.collision.pose.NumericPoseProgram;import io.github.r3neer.scalebrews.collision.api.spi.PoseEngine;import io.github.r3neer.scalebrews.collision.geometry.ModelGeometry;
public final class S59NumericConsumer {public static void main(String[]args)throws Exception{var g=new Gson();var capture=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray();var out=new ArrayList<Object>();int count=0;for(var row:capture){var object=row.getAsJsonObject();var program=NumericPoseProgram.validatedCopy(g.fromJson(object.get("program"),NumericPoseProgram.class));var bound=program.bind(program.geometry()).orElseThrow();var samples=new ArrayList<Object>();for(var sample:object.getAsJsonArray("samples")){var s=sample.getAsJsonObject();var channels=new TreeMap<String,Float>();s.getAsJsonObject("channels").entrySet().forEach(e->channels.put(e.getKey(),e.getValue().getAsFloat()));var matrices=program.geometry().transforms(bound.evaluate(new PoseEngine.Inputs(0,0,0,0,0,true,channels)).orElseThrow());var nativeMatrices=s.getAsJsonObject("matrices");if(!matrices.keySet().equals(nativeMatrices.keySet()))throw new AssertionError("S59 consumer part identity");for(var id:matrices.keySet()){float[] values=g.fromJson(nativeMatrices.get(id),float[].class);if(!new Matrix4f().set(values).equals(matrices.get(id),3e-6f))throw new AssertionError("S59 consumer native matrix "+id);count++;}samples.add(matrices.entrySet().stream().collect(java.util.stream.Collectors.toMap(Map.Entry::getKey,e->ModelGeometry.values(e.getValue()))));}out.add(samples);}Files.writeString(Path.of("common-matrices.json"),new GsonBuilder().setPrettyPrinting().create().toJson(out));System.out.println("S59_FOCAL_COMMON_PASS programs="+capture.size()+" matrices="+count+" clientVeto=true");}}
